// clang-format on
static_assert(W::measured(windows), "every window row hashes to its FNV-1a and its fixups lie inside it");
constexpr bool warn_in_window() {
    const W::Window& w = windows[window_warn_entry];
    for (unsigned k = 0; k < warn_length; ++k)
        if (w.rva != warn_rva || w.bytes[k] != warn_bytes[k]) return false;
    for (unsigned i = 0; i < 5; ++i) {
        const W::Window& r = windows[window_warn_ret_0 + i];
        if (r.rva != warn_ret_rva[i] || r.bytes[0] != 0xc2 || r.bytes[1] != warn_ret_pop || r.bytes[2] != 0) return false;
    }
    return true;
}
static_assert(warn_in_window(), "E's span and its five `ret 0xc` lie in their windows");
